// Optical nudges, in the icon's own frame (the group rotation carries them with the icon).
// Measured with the blur test (OPTICAL-ALIGNMENT R1 / checklist 1 and 4): arrows carry their
// visual weight toward the head, so they move back toward the tail; the check's weight sits low.
const OPTICAL_NUDGE = new Map<StrokeIconDef, [number, number]>([
  [strokeIcons["arrow-right"], [-1.6, 0]], // arrow-right: weight +1.63 units right of centre
  [strokeIcons["arrow-down"], [-1.6, 0]],
  [strokeIcons["arrow-left"], [-1.6, 0]],
  [strokeIcons["arrow-up"], [-1.6, 0]],
  [strokeIcons.check, [0, -0.9]], // check: weight +0.94 units below centre
]);

function nudgeOf(def: StrokeIconDef): [number, number] {
  return OPTICAL_NUDGE.get(def) ?? [0, 0];
}

function isSeg(v: unknown): v is Seg {
  return Array.isArray(v) && v.length === 4 && v.every((n) => typeof n === "number" && Number.isFinite(n));
}

// Registers a custom icon. Throws a TypeError unless it has exactly three finite line segments.
export function defineStrokeIcon(name: string, def: StrokeIconDef): void {
  if (!name) throw new TypeError("defineStrokeIcon: name must be a non-empty string");
  if (!Array.isArray(def.lines) || def.lines.length !== 3 || !def.lines.every(isSeg)) {
    throw new TypeError(`defineStrokeIcon("${name}"): lines must be exactly 3 [x1, y1, x2, y2] segments`);
  }
  if (def.hidden !== undefined && (!Array.isArray(def.hidden) || def.hidden.length !== 3)) {
    throw new TypeError(`defineStrokeIcon("${name}"): hidden must have exactly 3 booleans`);
  }
  strokeIcons[name] = def;
}

const warnedNames = new Set<string>();

function resolveStrokeIcon(name: string): StrokeIconDef {
  if (Object.prototype.hasOwnProperty.call(strokeIcons, name)) return strokeIcons[name];
  if (process.env.NODE_ENV !== "production" && !warnedNames.has(name)) {
    warnedNames.add(name);
    console.warn(`StrokeMorphIcon: unknown name "${name}", rendering "dot" instead.`);
  }
  return strokeIcons.dot;
}

// Effective geometry: hidden lines collapse onto the centroid of the visible endpoints.
const effCache = new WeakMap<StrokeIconDef, Seg[]>();

function effOf(def: StrokeIconDef): Seg[] {
  const cached = effCache.get(def);
  if (cached) return cached;
  const visible = [0, 1, 2].map((i) => !def.hidden?.[i]);
  let sx = 0;
  let sy = 0;
  let n = 0;
  def.lines.forEach(([x1, y1, x2, y2], i) => {
    if (!visible[i]) return;
    sx += x1 + x2;
    sy += y1 + y2;
    n += 2;
  });
  const cx = n ? sx / n : 12;
  const cy = n ? sy / n : 12;
  const eff = def.lines.map((seg, i): Seg => (visible[i] ? seg : [cx, cy, cx, cy]));
  effCache.set(def, eff);
  return eff;
}

function visibleOf(def: StrokeIconDef): boolean[] {
  return [0, 1, 2].map((i) => !def.hidden?.[i]);
}

interface Assignment {
  perm: number[]; // source line i goes to target line perm[i]
  flip: boolean[]; // swap that line's endpoints
}

const PERMS = [
  [0, 1, 2],
  [0, 2, 1],
  [1, 0, 2],
  [1, 2, 0],
  [2, 0, 1],
  [2, 1, 0],
];

// Best endpoint matching: 6 permutations, and per line the cheaper of the 2 endpoint flips
// (the 8 flip combinations reduce to this because each line's flip is independent).
function bestAssignment(src: Seg[], dst: Seg[]): Assignment {
  let best: Assignment = { perm: [0, 1, 2], flip: [false, false, false] };
  let bestCost = Infinity;
  for (const perm of PERMS) {
    let total = 0;
    const flip: boolean[] = [];
    for (let i = 0; i < 3; i++) {
      const [ax1, ay1, ax2, ay2] = src[i];
      const [bx1, by1, bx2, by2] = dst[perm[i]];
      const straight = (ax1 - bx1) ** 2 + (ay1 - by1) ** 2 + (ax2 - bx2) ** 2 + (ay2 - by2) ** 2;
      const crossed = (ax1 - bx2) ** 2 + (ay1 - by2) ** 2 + (ax2 - bx1) ** 2 + (ay2 - by1) ** 2;
      flip.push(crossed < straight);
      total += Math.min(straight, crossed);
    }
    if (total < bestCost) {
      bestCost = total;
      best = { perm: [...perm], flip };
    }
  }
  return best;
}

// Memoised per (from, to) pair of defs. Used when the icon has settled on `from`.
const matchCache = new WeakMap<StrokeIconDef, WeakMap<StrokeIconDef, Assignment>>();

function canonicalMatch(from: StrokeIconDef, to: StrokeIconDef): Assignment {
  let inner = matchCache.get(from);
  if (!inner) {
    inner = new WeakMap();
    matchCache.set(from, inner);
  }
  const cached = inner.get(to);
  if (cached) return cached;
  const result = bestAssignment(effOf(from), effOf(to));
  inner.set(to, result);
  return result;
}

// Shortest signed rotation from `from` to `to` (degrees), in (-180, 180].
function shortestDelta(from: number, to: number): number {
  return ((((to - from) % 360) + 540) % 360) - 180;
}

// Attributes are written to 2 decimals (0.005 of a 24-unit box). Finer precision only adds settle time.
const fmt = (v: number) => String(Math.round(v * 100) / 100);
const COORDS = ["x1", "y1", "x2", "y2"] as const;

interface MorphEls {
  group: SVGGElement;
  lines: (SVGLineElement | null)[];
}

// Owns the imperative morph. React renders once; every frame writes attributes through refs.
class Morph {
  private els: MorphEls | null = null;
  private cur = new Float64Array(12);
  private from = new Float64Array(12);
  private to = new Float64Array(12);
  private curAngle: number;
  private fromAngle: number;
  private toAngle: number;
  private curScale = 1;
  private fromScale = 1;
  private toScale = 1;
  private curNudge: [number, number];
  private fromNudge: [number, number];
  private toNudge: [number, number];
  private slotLine = [0, 1, 2]; // settled: element s shows canonical line slotLine[s]
  private targetLine = [0, 1, 2];
  private visibleTo = [true, true, true];
  private spring: SpringState = { x: 0, v: 0 };
  private written: (string | undefined)[] = [];
  private strokeWidth = 2;
  private active = false;
  private cfg = DEFAULT_SPRING;
  target: StrokeIconDef;

  constructor(def: StrokeIconDef) {
    this.target = def;
    effOf(def).forEach((seg, s) => this.to.set(seg, s * 4));
    this.cur.set(this.to);
    this.from.set(this.to);
    this.curAngle = this.fromAngle = this.toAngle = def.rotation ?? 0;
    this.curScale = this.fromScale = this.toScale = def.strokeScale ?? 1;
    this.curNudge = this.fromNudge = this.toNudge = nudgeOf(def);
  }

  bind(els: MorphEls) {
    this.els = els;
    this.paint(1);
  }

  setConfig(cfg: { stiffness: number; damping: number; mass: number }) {
    this.cfg = cfg;
  }

  setStrokeWidth(strokeWidth: number) {
    this.strokeWidth = strokeWidth;
    this.paint(this.active ? this.spring.x : 1);
  }

  retarget(next: StrokeIconDef, reduce: boolean) {
    const prev = this.target;
    const sameGroup = !!next.group && next.group === prev.group;
    this.target = next;

    if (!sameGroup) {
      let assignment: Assignment;
      if (this.active) {
        // Mid-flight: match from the current lerped geometry, not from a settled def.
        const current: Seg[] = [0, 1, 2].map((s) => [
          this.cur[s * 4],
          this.cur[s * 4 + 1],
          this.cur[s * 4 + 2],
          this.cur[s * 4 + 3],
        ]);
        assignment = bestAssignment(current, effOf(next));
      } else {
        assignment = canonicalMatch(prev, next);
      }
      const eff = effOf(next);
      const visible = visibleOf(next);
      for (let s = 0; s < 3; s++) {
        const c = this.active ? s : this.slotLine[s];
        const t = this.active ? assignment.perm[s] : assignment.perm[c];
        const flip = this.active ? assignment.flip[s] : assignment.flip[c];
        this.targetLine[s] = t;
        const [x1, y1, x2, y2] = eff[t];
        const seg: Seg = flip ? [x2, y2, x1, y1] : [x1, y1, x2, y2];
        this.to.set(seg, s * 4);
        this.visibleTo[s] = visible[t];
      }
      // A line that changes visibility fades over 120ms ease-out, or instantly when reduced.
      this.applyVisibility(reduce);
    }

    this.fromAngle = this.curAngle;
    this.fromScale = this.curScale;
    this.fromNudge = [this.curNudge[0], this.curNudge[1]];
    this.from.set(this.cur);
    this.toAngle = this.curAngle + shortestDelta(this.curAngle, next.rotation ?? 0);
    this.toScale = next.strokeScale ?? 1;
    this.toNudge = nudgeOf(next);

    if (reduce) {
      this.settle();
      return;
    }
    this.spring.x = 0; // keep the velocity so an interrupted move carries its momentum
    this.active = true;
  }

  private applyVisibility(reduce: boolean) {
    const els = this.els;
    if (!els) return;
    for (let s = 0; s < 3; s++) {
      const line = els.lines[s];
      if (!line) continue;
      line.style.transition = reduce ? "none" : `opacity 120ms ${easeCss.out}`;
      line.style.opacity = this.visibleTo[s] ? "1" : "0";
    }
  }

  // Frame step for useVisibleLoop. Returns false when idle.
  step(dt: number): boolean {
    if (!this.active) return false;
    stepSpring(this.spring, 1, this.cfg, dt);
    if (Math.abs(this.spring.x - 1) < 5e-4 && Math.abs(this.spring.v) < 5e-3) {
      this.settle();
      return false;
    }
    this.paint(this.spring.x);
    return true;
  }

  // Snap to the exact canonical geometry of the target and go idle.
  private settle() {
    const eff = effOf(this.target);
    for (let s = 0; s < 3; s++) {
      this.slotLine[s] = this.targetLine[s];
      const seg = eff[this.targetLine[s]];
      this.to.set(seg, s * 4);
    }
    this.from.set(this.to);
    this.fromAngle = this.toAngle;
    this.curAngle = this.toAngle;
    this.fromScale = this.toScale;
    this.curScale = this.toScale;
    this.fromNudge = [this.toNudge[0], this.toNudge[1]];
    this.curNudge = [this.toNudge[0], this.toNudge[1]];
    this.active = false;
    this.spring.x = 1;
    this.spring.v = 0;
    this.paint(1);
  }

  private paint(p: number) {
    const els = this.els;
    if (!els) return;
    for (let s = 0; s < 3; s++) {
      const line = els.lines[s];
      for (let k = 0; k < 4; k++) {
        const i = s * 4 + k;
        const v = this.from[i] + (this.to[i] - this.from[i]) * p;
        this.cur[i] = v;
        const str = fmt(v);
        if (line && this.written[i] !== str) {
          line.setAttribute(COORDS[k], str);
          this.written[i] = str;
        }
      }
    }
    this.curAngle = this.fromAngle + (this.toAngle - this.fromAngle) * p;
    this.curScale = this.fromScale + (this.toScale - this.fromScale) * p;
    const nx = this.fromNudge[0] + (this.toNudge[0] - this.fromNudge[0]) * p;
    const ny = this.fromNudge[1] + (this.toNudge[1] - this.fromNudge[1]) * p;
    this.curNudge = [nx, ny];
    const transform = `rotate(${fmt(this.curAngle)} 12 12) translate(${fmt(nx)} ${fmt(ny)})`;
    if (this.written[12] !== transform) {
      els.group.setAttribute("transform", transform);
      this.written[12] = transform;
    }
    const sw = fmt(this.strokeWidth * this.curScale);
    if (this.written[13] !== sw) {
      els.group.setAttribute("stroke-width", sw);
      this.written[13] = sw;
    }
  }
}

export function StrokeMorphIcon({
  name,
  size = 24,
  strokeWidth = 2,
  color = "currentColor",
  spring,
  spin,
  label,
  className,
}: StrokeMorphIconProps) {
  const reduceMotion = useReducedMotion() === true;
  const def = resolveStrokeIcon(name);

  // Initial markup only. After mount, attributes are owned by the Morph, so these
  // constants never change and React never overwrites an in-flight frame.
  const [initial] = useState(() => {
    const eff = effOf(def);
    const visible = visibleOf(def);
    return {
      segs: eff,
      visible,
      transform: `rotate(${def.rotation ?? 0} 12 12) translate(${nudgeOf(def).map(fmt).join(" ")})`,
      strokeWidth: fmt(strokeWidth * (def.strokeScale ?? 1)),
    };
  });
  const [morph] = useState(() => new Morph(def));

  const svgRef = useRef<SVGSVGElement>(null);
  const groupRef = useRef<SVGGElement>(null);
  const lineRefs = useRef<(SVGLineElement | null)[]>([null, null, null]);

  // The <svg> stays the root (icon-with-label rules target `>svg`). The loop hook only reads
  // the element's box and dataset, which SVG elements also have.
  const loop = useVisibleLoop(svgRef as RefObject<HTMLElement | null>, (dt) => morph.step(dt));

  useLayoutEffect(() => {
    if (!groupRef.current) return;
    morph.bind({ group: groupRef.current, lines: lineRefs.current });
  }, [morph]);

  useLayoutEffect(() => {
    morph.setConfig(spring ?? DEFAULT_SPRING);
  });

  useLayoutEffect(() => {
    if (morph.target === def) return;
    morph.retarget(def, reduceMotion);
    if (!reduceMotion) loop.wake();
  }, [def, reduceMotion, morph, loop]);

  useLayoutEffect(() => {
    morph.setStrokeWidth(strokeWidth);
  }, [morph, strokeWidth]);

  const spinning = (spin ?? def.spin) === true;

  return (
    <svg
      ref={svgRef}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke={color}
      strokeLinecap="round"
      strokeLinejoin="round"
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      className={cn("shrink-0", className)}
    >
      <g
        className={spinning ? "motion-safe:animate-spin" : undefined}
        style={{ transformBox: "view-box", transformOrigin: "12px 12px" }}
      >
        <g ref={groupRef} strokeWidth={initial.strokeWidth} transform={initial.transform}>
          {initial.segs.map(([x1, y1, x2, y2], i) => (
            <line
              key={i}
              ref={(el) => {
                lineRefs.current[i] = el;
              }}
              x1={x1}
              y1={y1}
              x2={x2}
              y2={y2}
              style={{ opacity: initial.visible[i] ? 1 : 0 }}
            />
          ))}
        </g>
      </g>
    </svg>
  );
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

"use client";

import { useCallback, useEffect, useMemo, useRef, type RefObject } from "react";

export interface VisibleLoopOptions {
  enabled?: boolean;
  fpsCap?: number;
  rootMargin?: string;
}

/**
 * Runs `frame(dt, t)` on requestAnimationFrame while the element is near the viewport,
 * the tab is visible and `enabled` is not false. Return `false` from `frame` to go idle
 * until `wake()` is called. Writes `data-loop` on the element: running, idle or paused.
 */
export function useVisibleLoop(
  ref: RefObject<HTMLElement | null>,
  frame: (dt: number, t: number) => boolean | void,
  opts?: VisibleLoopOptions,
): { wake: () => void } {
  const enabled = opts?.enabled !== false;
  const fpsCap = opts?.fpsCap ?? 0;
  const rootMargin = opts?.rootMargin ?? "96px";

  const frameRef = useRef(frame);
  useEffect(() => {
    frameRef.current = frame;
  }, [frame]);

  const wakeRef = useRef<() => void>(() => {});
  const wake = useCallback(() => wakeRef.current(), []);

  useEffect(() => {
    const el = ref.current;
    if (!el || typeof window === "undefined") return;

    let wants = true; // false once the frame callback returns false
    let inView = false;
    let raf = 0;
    let last = 0;
    let t = 0;
    const minFrame = fpsCap > 0 ? 1000 / fpsCap : 0;

    const canRun = () => enabled && inView && document.visibilityState === "visible";
    const stop = () => {
      if (raf) cancelAnimationFrame(raf);
      raf = 0;
    };

    const update = () => {
      if (!enabled) {
        stop();
        el.dataset.loop = "paused";
        return;
      }
      if (!wants) {
        stop();
        el.dataset.loop = "idle";
        return;
      }
      if (!canRun()) {
        stop();
        el.dataset.loop = "paused";
        return;
      }
      el.dataset.loop = "running";
      if (!raf) {
        last = performance.now();
        raf = requestAnimationFrame(tick);
      }
    };

    const tick = (now: number) => {
      raf = 0;
      if (!canRun() || !wants) {
        update();
        return;
      }
      const elapsed = now - last;
      if (minFrame && elapsed < minFrame - 0.5) {
        raf = requestAnimationFrame(tick);
        return;
      }
      last = now;
      const dt = Math.min(0.05, Math.max(0, elapsed / 1000));
      t += dt;
      const keep = frameRef.current(dt, t);
      if (keep === false) {
        wants = false;
        update();
        return;
      }
      raf = requestAnimationFrame(tick);
    };

    const observer = new IntersectionObserver(
      ([entry]) => {
        inView = entry.isIntersecting;
        update();
      },
      { rootMargin },
    );
    observer.observe(el);

    const onVisibility = () => update();
    document.addEventListener("visibilitychange", onVisibility);

    wakeRef.current = () => {
      wants = true;
      update();
    };

    update();

    return () => {
      stop();
      observer.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      wakeRef.current = () => {};
    };
  }, [ref, enabled, fpsCap, rootMargin]);

  return useMemo(() => ({ wake }), [wake]);
}

// matchMedia based check. False on the server.
export function isCoarsePointer(): boolean {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") return false;
  return window.matchMedia("(pointer: coarse)").matches;
}

// Pure spring math, no React. Units: stiffness k, damping d (coefficient), mass m, time in seconds.

export interface SpringConfig {
  stiffness: number;
  damping: number;
  mass: number;
}

export interface SpringState {
  x: number;
  v: number;
}

// Damping ratio zeta = d / (2 * sqrt(k * m)).
export function dampingRatio(c: SpringConfig): number {
  return c.damping / (2 * Math.sqrt(c.stiffness * c.mass));
}

// Exact solution of y'' = -(k/m) y - (d/m) y' for displacement y0 and velocity v0 at time t.
// Returns displacement and velocity together so stepping can be exact, not integrated.
function solveLinear(t: number, c: SpringConfig, y0: number, v0: number): { y: number; v: number } {
  const w0 = Math.sqrt(c.stiffness / c.mass);
  const z = dampingRatio(c);

  if (Math.abs(z - 1) < 1e-9) {
    // Critically damped.
    const e = Math.exp(-w0 * t);
    const b = v0 + w0 * y0;
    return { y: e * (y0 + b * t), v: e * (b - w0 * (y0 + b * t)) };
  }
  if (z < 1) {
    // Underdamped.
    const wd = w0 * Math.sqrt(1 - z * z);
    const a = z * w0;
    const B = (v0 + a * y0) / wd;
    const e = Math.exp(-a * t);
    const cos = Math.cos(wd * t);
    const sin = Math.sin(wd * t);
    return {
      y: e * (y0 * cos + B * sin),
      v: e * (-a * (y0 * cos + B * sin) + wd * (-y0 * sin + B * cos)),
    };
  }
  // Overdamped.
  const s = w0 * Math.sqrt(z * z - 1);
  const r1 = -z * w0 + s;
  const r2 = -z * w0 - s;
  const B = (v0 - r1 * y0) / (r2 - r1);
  const A = y0 - B;
  const e1 = Math.exp(r1 * t);
  const e2 = Math.exp(r2 * t);
  return { y: A * e1 + B * e2, v: A * r1 * e1 + B * r2 * e2 };
}

// Analytic position at time t for a spring from `from` to `to` with initial velocity v0.
export function springAt(t: number, c: SpringConfig, from = 0, to = 1, v0 = 0): number {
  return to + solveLinear(t, c, from - to, v0).y;
}

// Overshoot as a fraction of the total travel. Zero when critically or overdamped.
export function overshoot(c: SpringConfig): number {
  const z = dampingRatio(c);
  if (z >= 1) return 0;
  return Math.exp((-Math.PI * z) / Math.sqrt(1 - z * z));
}

// Seconds until the spring stays within epsilon of its target (fraction of travel).
// Found by scanning backwards from a bound derived from the slowest decay rate.
export function settleTime(c: SpringConfig, epsilon = 0.001): number {
  const w0 = Math.sqrt(c.stiffness / c.mass);
  const z = dampingRatio(c);
  const slowest = z < 1 ? z * w0 : (z - Math.sqrt(z * z - 1)) * w0;
  const tEnd = (Math.log(1 / epsilon) / slowest) * 1.5 + 0.05;
  const steps = 4000;
  const dt = tEnd / steps;
  const band = epsilon;
  let last = 0;
  for (let i = 0; i <= steps; i++) {
    const t = i * dt;
    if (Math.abs(springAt(t, c, 1, 0, 0)) >= band) last = t;
  }
  return last + dt;
}

// Advances the state by dt towards `target`. Uses the exact solution of the linear spring
// (no integration), so it tracks springAt to rounding error at any step size and stays stable
// for stiff configs where a fixed-step integrator drifts.
export function stepSpring(s: SpringState, target: number, c: SpringConfig, dt: number): void {
  if (dt <= 0) return;
  const r = solveLinear(dt, c, s.x - target, s.v);
  s.x = target + r.y;
  s.v = r.v;
}

// Shared springs, easings and durations. Components import these instead of inventing values.

export const springs = {
  press: { type: "spring", stiffness: 500, damping: 30, mass: 0.6 },
  snappy: { type: "spring", stiffness: 400, damping: 25, mass: 1 },
  standard: { type: "spring", stiffness: 300, damping: 30, mass: 0.8 },
  soft: { type: "spring", stiffness: 200, damping: 25, mass: 1.2 },
  settle: { type: "spring", stiffness: 380, damping: 30, mass: 0.8 },
  blurIn: { type: "spring", stiffness: 400, damping: 28, mass: 0.6 },
} as const;

export const ease = {
  out: [0.23, 1, 0.32, 1],
  inOut: [0.77, 0, 0.175, 1],
  drawer: [0.32, 0.72, 0, 1],
} as const;

export const easeCss = {
  out: "cubic-bezier(0.23,1,0.32,1)",
  inOut: "cubic-bezier(0.77,0,0.175,1)",
  drawer: "cubic-bezier(0.32,0.72,0,1)",
} as const;

export const durations = { press: 140, tooltip: 160, menu: 200, panel: 280 } as const; // ms

// Cubic bezier easing for canvas and rAF code. Returns progress y for input x in [0, 1].
export function cubicBezier(x1: number, y1: number, x2: number, y2: number): (t: number) => number {
  const cx = 3 * x1;
  const bx = 3 * (x2 - x1) - cx;
  const ax = 1 - cx - bx;
  const cy = 3 * y1;
  const by = 3 * (y2 - y1) - cy;
  const ay = 1 - cy - by;
  const sampleX = (s: number) => ((ax * s + bx) * s + cx) * s;
  const sampleY = (s: number) => ((ay * s + by) * s + cy) * s;
  const sampleDX = (s: number) => (3 * ax * s + 2 * bx) * s + cx;

  const solveX = (x: number) => {
    let s = x;
    for (let i = 0; i < 8; i++) {
      const err = sampleX(s) - x;
      if (Math.abs(err) < 1e-6) return s;
      const d = sampleDX(s);
      if (Math.abs(d) < 1e-6) break;
      s -= err / d;
    }
    let lo = 0;
    let hi = 1;
    s = x;
    while (lo < hi) {
      const v = sampleX(s);
      if (Math.abs(v - x) < 1e-6) return s;
      if (x > v) lo = s;
      else hi = s;
      s = (lo + hi) / 2;
      if (hi - lo < 1e-7) break;
    }
    return s;
  };

  return (t: number) => {
    if (t <= 0) return 0;
    if (t >= 1) return 1;
    return sampleY(solveX(t));
  };
}
